/** 分层蓝图复用实机方块物品图；图标本身不代表放置后的属性朝向。 */
public final class LayoutCardService {
    private static final ObjectMapper JSON=new ObjectMapper();private final DatabaseBuilder db;private final Path directory;
    public LayoutCardService(DatabaseBuilder db,Path directory){this.db=db;this.directory=directory;}
    public Path render(String profile,String category,String id,boolean cacheOnly,Integer layer)throws Exception {
        if(!Set.of("multiblocks","structure_templates").contains(category))throw new IllegalArgumentException("此类别没有方块布局");if(!Objects.equals(profile,RuntimeKnowledgeStore.active(db)))throw new IllegalArgumentException("请先选择匹配的快照图标环境");JsonNode row;
        try(var c=db.getConnection();var p=c.prepareStatement("SELECT record_data FROM rag_runtime_record WHERE profile_id=? AND category=? AND record_id=?")){p.setString(1,profile);p.setString(2,category);p.setString(3,id);try(var rows=p.executeQuery()){if(!rows.next())throw new IllegalArgumentException("布局记录不存在");row=JSON.readTree(rows.getString(1));}}
        if(!RuntimeStructures.renderable(category,row))throw new IllegalArgumentException("布局仅有元数据、未适配或采集失败，请查看原因");var icons=new ItemIconService(db,directory).snapshot();String key=BuildRequest.fingerprint("layout-v2\n"+profile+"\n"+icons.revision()+"\n"+category+"\n"+row+"\nlayer="+layer);Path folder=directory.resolve("generated/layouts"),file=folder.resolve(key+".png"),meta=folder.resolve(key+".json");
        if(Files.isRegularFile(file)&&Files.isRegularFile(meta))try{if(JSON.readTree(meta.toFile()).path("sha256").asText().equals(ArtifactFingerprint.sha256(file)))return file;}catch(java.io.IOException invalid){}if(cacheOnly)return null;var image=draw(category,row,icons,layer);Files.createDirectories(folder);Path tmp=Files.createTempFile(folder,"layout-",".png");try{javax.imageio.ImageIO.write(image,"png",tmp.toFile());Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}Files.writeString(meta,JSON.createObjectNode().put("sha256",ArtifactFingerprint.sha256(file)).put("fingerprint",key).toPrettyString());return file;
    }
    public static BufferedImage draw(String category,JsonNode row,ItemIconService.Snapshot icons,Integer requestedLayer)throws Exception {
        RuntimeStructures.validate(category,row);if(!RuntimeStructures.renderable(category,row))throw new IllegalArgumentException("没有完整布局");int[] size=RuntimeStructures.triple(row.path("size"));int[] origin=category.equals("multiblocks")?RuntimeStructures.triple(row.path("origin")):new int[3];int minY=-origin[1],maxY=size[1]-origin[1]-1;if(size[0]<1||size[2]<1||size[0]>64||size[2]>64)throw new IllegalArgumentException("布局平面超过64×64，请查看完整JSON");
        if(requestedLayer==null&&size[1]>8)throw new IllegalArgumentException("模板超过8层，请取消分层总览并指定Y层");if(requestedLayer!=null&&(requestedLayer<minY||requestedLayer>maxY))throw new IllegalArgumentException("Y层范围："+minY+"～"+maxY);var layers=new ArrayList<Integer>();if(requestedLayer!=null)layers.add(requestedLayer);else for(int y=minY;y<=maxY;y++)layers.add(y);
        int cell=18*Math.min(4,Math.max(1,38/Math.max(size[0],size[2]))),panelWidth=Math.max(240,size[0]*cell+56),panelHeight=size[2]*cell+100,columns=layers.size()<=3&&panelWidth<=320?layers.size():1;int width=Math.max(1080,panelWidth*columns+48);var materials=RuntimeStructures.materials(category,row);int materialLines=Math.min(40,materials.size());int gridHeight=((layers.size()+columns-1)/columns)*panelHeight;int height=200+gridHeight+materialLines*34+140;
        if((long)width*height>8000000)throw new IllegalArgumentException("布局图片超过像素预算，请选单层");var cells=RuntimeStructures.cells(category,row);var indices=new LinkedHashMap<String,Integer>();for(String block:materials.keySet())indices.put(block,indices.size()+1);var byPos=new HashMap<String,RuntimeStructures.Cell>();for(var c:cells)byPos.put(c.x()+","+c.y()+","+c.z(),c);
        var image=new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();try{
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);g.setColor(new Color(198,198,198));g.fillRect(0,0,width,height);g.setColor(new Color(45,45,45));g.setFont(CardFont.at(Font.BOLD,28));line(g,row.path("name").asText(row.path("id").asText())+" · 分层布局",24,40,width-48);g.setFont(CardFont.at(Font.PLAIN,19));g.drawString("北 ↑（Z−） · 东 →（X+） · Y向上；"+(category.equals("multiblocks")?"坐标相对控制器，示例允许的替代条件见正文":"资源模板，第1套调色板；处理器与jigsaw可能改变放置结果"),24,77);g.drawString("使用实机默认物品图标；方块实际状态以属性为准。这是布局图，不是游戏世界截图。",24,107);g.drawString("尺寸 "+size[0]+"×"+size[1]+"×"+size[2]+"；"+(requestedLayer==null?"按Y由低到高展示":"仅展示Y="+requestedLayer)+"；格内序号对应下方材料表，未指定单元不自动等于空气。",24,137);
            for(int index=0;index<layers.size();index++){int layer=layers.get(index),px=24+(index%columns)*panelWidth,py=180+(index/columns)*panelHeight;g.setColor(new Color(45,45,45));g.setFont(CardFont.at(Font.BOLD,22));g.drawString("Y = "+layer,px,py);for(int z=0;z<size[2];z++)for(int x=0;x<size[0];x++){int gx=px+x*cell,gy=py+20+z*cell;MinecraftSlot.draw(g,gx,gy,cell/18);var current=byPos.get((x-origin[0])+","+layer+","+(z-origin[2]));if(current==null)continue;if(RuntimeStructures.air(current.block())){g.setColor(new Color(65,65,65));g.setFont(CardFont.at(Font.PLAIN,Math.min(18,cell/2)));g.drawString("空",gx+3,gy+cell-4);continue;}var icon=icons.item(current.block(),false,null);if(icon.image()!=null)g.drawImage(icon.image(),gx+3,gy+3,cell-6,cell-6,null);else{g.setColor(Color.WHITE);g.setFont(CardFont.at(Font.BOLD,Math.min(25,cell-4)));g.drawString("?",gx+cell/3,gy+cell*3/4);}g.setFont(CardFont.at(Font.BOLD,Math.min(18,cell/3)));shadow(g,String.valueOf(indices.get(current.block())),gx+3,gy+Math.max(12,cell/4));String facing=current.properties().path("facing").asText();String arrow=switch(facing){case "north"->"↑";case "east"->"→";case "south"->"↓";case "west"->"←";default->"";};if(!arrow.isEmpty())shadow(g,arrow,gx+cell-16,gy+cell-4);}}
            int y=190+gridHeight;g.setColor(new Color(45,45,45));g.setFont(CardFont.at(Font.BOLD,23));g.drawString("方块对照（全布局计数；非物品消耗量）",24,y);g.setFont(CardFont.at(Font.PLAIN,20));int shown=0;for(var entry:materials.entrySet()){if(++shown>40)break;y+=34;var icon=icons.item(entry.getKey(),false,null);if(icon.image()!=null)g.drawImage(icon.image(),25,y-24,28,28,null);g.setColor(new Color(45,45,45));line(g,indices.get(entry.getKey())+" · "+icon.name()+" × "+entry.getValue()+"   "+entry.getKey(),66,y,width-92);}y+=42;g.setColor(new Color(45,45,45));g.drawString(materials.size()>40?"其余材料与完整条件见目录JSON。":(category.equals("multiblocks")?"组装检查、供能、输入与操作步骤见对应说明；配方单独以当前快照规则为准。":"资源模板不保证原样放置；备选调色板、处理器和jigsaw可能改变结果。"),24,y);
        }finally{g.dispose();}return image;
    }
    private static void shadow(Graphics2D g,String value,int x,int y){g.setColor(new Color(50,50,50));g.drawString(value,x+1,y+1);g.setColor(Color.WHITE);g.drawString(value,x,y);}
    private static void line(Graphics2D g,String value,int x,int y,int width){while(value.length()>1&&g.getFontMetrics().stringWidth(value)>width)value=value.substring(0,value.length()-2)+"…";g.drawString(value,x,y);}
    /** 只渲染一条指定多方块：用于结构化查询已经定位到结构、但向量结果里没有它的回合。 */
    public void attachOne(QaPipeline.QaResult result,String id)throws Exception {
        String profile=RuntimeKnowledgeStore.active(db);if(profile==null||id==null||id.isBlank())return;
        String prefix="mkb-runtime:"+profile+"/multiblocks/"+id;
        var file=render(profile,"multiblocks",id,false,null);
        var asset=new ImageAssetStore(directory).put(Files.readAllBytes(file));
        String source="s"+BuildRequest.fingerprint(prefix).substring(0,20);
        String caption="多方块分层工作示例："+id;
        var sources=new ArrayList<>(result.artifacts.sources());
        var pictures=new ArrayList<>(result.artifacts.pictures());
        sources.add(new AnswerArtifacts.Source(source,prefix,id,prefix,"实机多方块声明",null,"RUNTIME_SNAPSHOT",caption));
        pictures.add(new AnswerArtifacts.Picture("i"+asset.id().substring(0,20),asset.id(),asset.relativePath(),caption,source,"RUNTIME_RULE",java.util.List.of(),caption,null,null,null));
        result.artifacts=new AnswerArtifacts(result.artifacts.scopeId(),result.artifacts.scopeLabel(),sources,pictures,result.artifacts.citedSourceIds());
    }    public void attach(QaPipeline.QaResult result,String question){if(question==null||!question.matches("(?is).*(多方块|结构|布局|搭建|组装|朝向|锻炉|制作|合成|获取|获得|加工|材料|multiblock).*"))return;String profile=RuntimeKnowledgeStore.active(db);if(profile==null)return;var seen=new HashSet<String>();for(var hit:result.vectorResults){if(seen.size()>=3)break;if(hit.score()<=0.3||!Set.of("runtime_multiblocks","runtime_structure_templates").contains(hit.type()))continue;String category=hit.type().substring(8);String prefix="mkb-runtime:"+profile+"/"+category+"/";if(!hit.sourcePath().startsWith(prefix))continue;String id=hit.sourcePath().substring(prefix.length());if(category.equals("structure_templates")&&!question.contains(id))continue;if(!seen.add(category+id))continue;try{Integer layer=null;if(category.equals("structure_templates")){try(var c=db.getConnection();var p=c.prepareStatement("SELECT record_data FROM rag_runtime_record WHERE profile_id=? AND category='structure_templates' AND record_id=?")){p.setString(1,profile);p.setString(2,id);try(var rows=p.executeQuery()){if(!rows.next())continue;var row=JSON.readTree(rows.getString(1));if(!RuntimeStructures.renderable(category,row))continue;if(row.path("size").path(1).asInt()>8)layer=0;}}}var file=render(profile,category,id,false,layer);var asset=new ImageAssetStore(directory).put(Files.readAllBytes(file));String source="s"+BuildRequest.fingerprint(prefix+id).substring(0,20);var sources=new ArrayList<>(result.artifacts.sources());var pictures=new ArrayList<>(result.artifacts.pictures());sources.add(new AnswerArtifacts.Source(source,prefix+id,id,prefix+id,category.equals("multiblocks")?"实机多方块声明":"资源模板布局",null,"RUNTIME_SNAPSHOT",hit.chunkText()));pictures.add(new AnswerArtifacts.Picture("i"+asset.id().substring(0,20),asset.id(),asset.relativePath(),(category.equals("multiblocks")?"多方块分层工作示例：":"资源模板第1套调色板"+(layer==null?"分层示意：":"Y=0局部切片："))+id,source,"RUNTIME_RULE",java.util.List.of(hit.chunkId()),hit.chunkText()));result.artifacts=new AnswerArtifacts(result.artifacts.scopeId(),result.artifacts.scopeLabel(),sources,pictures,result.artifacts.citedSourceIds());}catch(Exception failure){result.mediaWarnings.add("布局图："+id+" · "+failure.getMessage());}}}
}
